cd /tmp && python3 - <<'PY'
import re, json, glob, os, collections
msgs={m["sha"]:m for m in json.load(open("/tmp/audit/msgs.json"))}
files=sorted(glob.glob("/home/runner/work/main-wt/S0*/E*.md"))
counts=collections.Counter()
orphans=collections.defaultdict(list)
for f in files:
    t=open(f,encoding="utf-8").read()
    for m in re.finditer(r"@\s*([0-9a-f]{40})", t):
        s=m.group(1); counts[s]+=1
        if s not in msgs: orphans[s].append(os.path.basename(f))
dups={s:c for s,c in counts.items() if c>1}
print("files:", len(files), "distinct SHAs recorded:", len(counts))
print("duplicated SHAs:", len(dups))
for s,c in list(dups.items())[:10]: print("  dup", s[:12], c, msgs.get(s,{}).get("speaker"))
print("orphan SHAs (not a Friend-Message commit):", len(orphans))
for s,fl in list(orphans.items())[:10]: print("  orphan", s[:12], fl)
PY
